from datetime import datetime, time


class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self.users: dict[str, dict[str, bool]] = {}

    def add_user(self, user: str) -> None:
        """Add a user with default notification preferences."""
        self.users[user] = {
            "email": True,
            "sms": False,
            "push": False,
        }

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        """Enable or disable a specific channel for a user."""
        if user not in self.users:
            self.add_user(user)
        if channel in self.CHANNELS:
            self.users[user][channel] = enabled

    def _is_quiet_hour(self, t: time) -> bool:
        """Check whether the given time falls within the configured quiet hours."""
        if self.quiet_start <= self.quiet_end:
            # Quiet window within the same calendar day (e.g., 01:00 to 05:00)
            return self.quiet_start <= t < self.quiet_end
        else:
            # Quiet window spanning midnight (e.g., 22:00 to 07:00)
            return t >= self.quiet_start or t < self.quiet_end

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self.users:
            return []

        user_prefs = self.users[user]
        is_quiet = self._is_quiet_hour(at.time())

        delivered_channels = []
        for channel in self.CHANNELS:
            if not user_prefs.get(channel, False):
                continue

            # During quiet hours, only email is delivered; sms and push are muted
            if is_quiet and channel != "email":
                continue

            delivered_channels.append(channel)

        return delivered_channels
